import{_ as a,c as t,o,ag as s}from"./chunks/framework.uGESq8iV.js";const h=JSON.parse('{"title":"Directus Template для AgencyOS","description":"","frontmatter":{},"headers":[],"relativePath":"guide/directus-template.md","filePath":"guide/directus-template.md","lastUpdated":1764669597000}'),r={name:"guide/directus-template.md"};function i(l,e,c,d,n,u){return o(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="directus-template-для-agencyos" tabindex="-1">Directus Template для AgencyOS <a class="header-anchor" href="#directus-template-для-agencyos" aria-label="Permalink to &quot;Directus Template для AgencyOS&quot;">​</a></h1><p>Цей розділ описує Directus‑темплейт, який постачається разом з проектом у директорії <code>./directus/template</code>.</p><p>Темплейт містить повну схему даних (колекції, поля, звʼязки), необхідну для роботи сайту та CRM‑частини AgencyOS.</p><h2 id="де-знаходиться-темплеит" tabindex="-1">Де знаходиться темплейт <a class="header-anchor" href="#де-знаходиться-темплеит" aria-label="Permalink to &quot;Де знаходиться темплейт&quot;">​</a></h2><ul><li><strong>Шлях у репозиторії:</strong> <code>./directus/template</code></li><li><strong>Призначення:</strong> швидко розгорнути усю схему Directus, не створюючи колекції вручну</li></ul><blockquote><p>Якщо ви використовуєте <strong>Directus Cloud</strong>, ви можете застосувати або віддалений темплейт через <code>directus-template-cli</code>, або локальний з цієї директорії (через імпорт у Directus чи CLI). Для self‑hosted сценаріїв локальний темплейт особливо зручний.</p></blockquote><h2 id="що-входить-у-темплеит" tabindex="-1">Що входить у темплейт <a class="header-anchor" href="#що-входить-у-темплеит" aria-label="Permalink to &quot;Що входить у темплейт&quot;">​</a></h2><p>Темплейт відображає схему, описану в розділі <a href="/directus-agency-os/architecture/data-schema.html">Архітектура / Data Schema</a>, і умовно поділяється на кілька блоків:</p><h3 id="_1-веб‐саит-marketing-site" tabindex="-1">1. Веб‑сайт (Marketing Site) <a class="header-anchor" href="#_1-веб‐саит-marketing-site" aria-label="Permalink to &quot;1. Веб‑сайт (Marketing Site)&quot;">​</a></h3><p>Колекції для публічного сайту:</p><ul><li><strong><code>pages</code> / <code>pages_blocks</code></strong> — динамічний Page Builder</li><li><strong><code>posts</code> / <code>categories</code></strong> — блог та категорії</li><li><strong><code>seo</code></strong> — SEO‑налаштування сторінок</li><li><strong><code>redirects</code></strong> — редіректи для старих URL</li></ul><p>Докладніше: <a href="/directus-agency-os/architecture/data-schema.html">Архітектура / Data Schema</a> та <a href="/directus-agency-os/components/page-builder.html">Компоненти / Page Builder</a>.</p><h3 id="_2-crm-agency-os" tabindex="-1">2. CRM / Agency OS <a class="header-anchor" href="#_2-crm-agency-os" aria-label="Permalink to &quot;2. CRM / Agency OS&quot;">​</a></h3><p>Колекції для операційної діяльності агентства:</p><ul><li><strong><code>organizations</code> / <code>organization_addresses</code> / <code>organization_contacts</code></strong> — організації та їх контакти</li><li><strong><code>contacts</code></strong> — окремі контактні особи</li><li><strong><code>os_deals</code> / <code>os_activity</code></strong> — угоди та sales‑активності</li><li><strong><code>os_projects</code> / <code>os_tasks</code></strong> — проекти та задачі</li><li><strong><code>os_invoices</code> / <code>os_items</code> / <code>os_tax_rates</code> / <code>os_payments</code></strong> — інвойси, позиції, податкові ставки, платежі</li><li><strong><code>os_subscriptions</code></strong> — підписки (якщо використовується)</li></ul><p>Докладніше: <a href="/directus-agency-os/architecture/data-schema.html">Архітектура / Data Schema</a> та розділи про Portal Layer.</p><h3 id="_3-proposals-пропозиціі" tabindex="-1">3. Proposals (Пропозиції) <a class="header-anchor" href="#_3-proposals-пропозиціі" aria-label="Permalink to &quot;3. Proposals (Пропозиції)&quot;">​</a></h3><p>Колекції для builderʼа пропозицій та e‑signature:</p><ul><li><strong><code>os_proposals</code></strong> — основна сутність пропозиції</li><li><strong><code>os_proposal_blocks</code></strong> — блоки контенту всередині пропозиції</li><li><strong><code>os_proposal_approvals</code></strong> — підписи та статуси погодження</li></ul><p>Ці колекції напряму використовуються в <code>layers/proposals/</code>. Докладніше: <a href="/directus-agency-os/layers/proposals.html">Layers / Proposals</a>.</p><h3 id="_4-системні-колекціі" tabindex="-1">4. Системні колекції <a class="header-anchor" href="#_4-системні-колекціі" aria-label="Permalink to &quot;4. Системні колекції&quot;">​</a></h3><ul><li><strong><code>globals</code></strong> — глобальні налаштування сайту (бренд, логотипи, соцмережі)</li><li><strong><code>help_articles</code> / <code>help_collections</code></strong> — база знань/довідка</li><li>Інші допоміжні колекції, які розширюють стандартні <code>directus_*</code></li></ul><p>Докладніше: <a href="/directus-agency-os/architecture/key-files.html">Архітектура / Key Files</a> та <a href="/directus-agency-os/api/server-utils.html">API / Server Utils</a>.</p><h2 id="як-застосувати-темплеит" tabindex="-1">Як застосувати темплейт <a class="header-anchor" href="#як-застосувати-темплеит" aria-label="Permalink to &quot;Як застосувати темплейт&quot;">​</a></h2><p>Є два основні сценарії:</p><h3 id="варіант-a-directus-template-cli-як-і-раніше" tabindex="-1">Варіант A: <code>directus-template-cli</code> (як і раніше) <a class="header-anchor" href="#варіант-a-directus-template-cli-як-і-раніше" aria-label="Permalink to &quot;Варіант A: `directus-template-cli` (як і раніше)&quot;">​</a></h3><p>Як описано в <a href="/directus-agency-os/guide/getting-started.html#крок-3-застосування-шаблону-agencyos">Початок роботи</a>:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> directus-template-cli@latest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apply</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ol><li>Оберіть <code>Agency OS</code> у списку темплейтів</li><li>Вкажіть URL Directus інстансу</li><li>Вставте static token admin‑користувача</li></ol><h3 id="варіант-b-локальнии-темплеит-з-directus-template" tabindex="-1">Варіант B: Локальний темплейт з <code>./directus/template</code> <a class="header-anchor" href="#варіант-b-локальнии-темплеит-з-directus-template" aria-label="Permalink to &quot;Варіант B: Локальний темплейт з `./directus/template`&quot;">​</a></h3><p>Для випадків, коли темплейт вже знаходиться поруч з кодом (цей репозиторій):</p><ol><li>Переконайтеся, що Directus інстанс запущений та доступний</li><li>Відкрийте адмінку Directus або скористайтеся CLI відповідно до офіційної документації Directus Templates</li><li>Імпортуйте темплейт з директорії <code>./directus/template</code> (наприклад, через <code>directus schema apply</code> або UI‑імпорт, залежно від вашого робочого процесу)</li></ol><p>Офіційна документація Directus щодо темплейтів/схеми:</p><ul><li><a href="https://docs.directus.io" target="_blank" rel="noreferrer"><code>https://docs.directus.io</code></a></li></ul><blockquote><p>Конкретна команда імпорту може відрізнятися залежно від версії Directus та інструменту, який ви використовуєте. Орієнтуйтесь на офіційні гіди Directus та приклади у вашому CI/CD.</p></blockquote><h2 id="де-дізнатись-більше" tabindex="-1">Де дізнатись більше <a class="header-anchor" href="#де-дізнатись-більше" aria-label="Permalink to &quot;Де дізнатись більше&quot;">​</a></h2><ul><li><a href="/directus-agency-os/architecture/data-schema.html">Архітектура / Data Schema</a> — повний опис колекцій</li><li><a href="/directus-agency-os/modules/directus.html">Модулі / Directus</a> — як Nuxt‑модуль підключається до Directus</li><li><a href="/directus-agency-os/layers/portal.html">Layers / Portal</a> та <a href="/directus-agency-os/layers/proposals.html">Layers / Proposals</a> — як шаблон використовують Portal &amp; Proposals Layers</li></ul><p>{ &quot;cells&quot;: [], &quot;metadata&quot;: { &quot;language_info&quot;: { &quot;name&quot;: &quot;python&quot; } }, &quot;nbformat&quot;: 4, &quot;nbformat_minor&quot;: 2 }</p>',38)])])}const g=a(r,[["render",i]]);export{h as __pageData,g as default};
